-- Phase 23B RLS: derived intelligence only; service writes, human review/governance is explicit.
CREATE OR REPLACE FUNCTION public.brain_phase23b_version_guard() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP IN ('UPDATE','DELETE') AND OLD.status IN ('active','retired','archived') THEN RAISE EXCEPTION 'Published Brain metadata versions are immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.brain_phase23b_model_guard() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='production_approved' THEN RAISE EXCEPTION 'Phase 23B model registry is metadata-only; production approval is prohibited'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.brain_recommendation_guard() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.review_status NOT IN ('proposed','awaiting_review') THEN RAISE EXCEPTION 'Brain recommendations must begin proposed or awaiting review'; END IF; IF NEW.domain_action_link_metadata ?| ARRAY['execute','command','mutation','workflow_execution'] THEN RAISE EXCEPTION 'Brain recommendations cannot contain operational execution metadata'; END IF; IF TG_OP='UPDATE' AND OLD.review_status IN ('accepted','accepted_for_domain_review','partially_accepted','rejected','superseded','expired','dismissed') THEN RAISE EXCEPTION 'Final Brain recommendation reviews are immutable'; END IF; IF TG_OP='UPDATE' AND NEW.review_status IN ('accepted','accepted_for_domain_review','partially_accepted','rejected') AND (NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL) THEN RAISE EXCEPTION 'Brain recommendation review requires reviewer and timestamp'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.brain_phase23b_append_audit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.brain_audit_logs(company_id,entity_type,entity_id,event_type,actor_id,metadata) VALUES(coalesce(NEW.company_id,OLD.company_id),TG_TABLE_NAME,coalesce(NEW.id,OLD.id),'brain.'||lower(TG_OP),auth.uid(),jsonb_build_object('phase','23B')); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['brain_feature_registry','brain_feature_versions','brain_feature_calculations','brain_rule_evaluations','brain_evidence_conflicts','brain_confidence_policies','brain_insight_correlations','brain_explanations','brain_query_definitions','brain_query_executions','brain_intelligence_quality','brain_outcome_records'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.brain_phase23b_append_audit()',t||'_audit',t); END LOOP; END $$;
ALTER TABLE public.brain_prompt_registry ENABLE ROW LEVEL SECURITY; ALTER TABLE public.brain_prompt_versions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.brain_model_registry ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.brain_prompt_registry,public.brain_prompt_versions,public.brain_model_registry TO authenticated; GRANT ALL ON public.brain_prompt_registry,public.brain_prompt_versions,public.brain_model_registry TO service_role;
GRANT INSERT,UPDATE,DELETE ON public.brain_feature_registry,public.brain_feature_versions,public.brain_confidence_policies,public.brain_query_definitions,public.brain_prompt_registry,public.brain_prompt_versions,public.brain_model_registry TO authenticated;
GRANT INSERT ON public.brain_feature_calculations,public.brain_rule_evaluations,public.brain_evidence_conflicts,public.brain_insight_correlations,public.brain_explanations,public.brain_query_executions,public.brain_intelligence_quality,public.brain_outcome_records TO authenticated;
GRANT UPDATE ON public.brain_evidence_conflicts,public.brain_intelligence_quality TO authenticated;
CREATE TRIGGER brain_feature_version_immutable BEFORE UPDATE OR DELETE ON public.brain_feature_versions FOR EACH ROW EXECUTE FUNCTION public.brain_phase23b_version_guard();
CREATE TRIGGER brain_prompt_version_immutable BEFORE UPDATE OR DELETE ON public.brain_prompt_versions FOR EACH ROW EXECUTE FUNCTION public.brain_phase23b_version_guard();
CREATE TRIGGER brain_model_metadata_only BEFORE INSERT OR UPDATE ON public.brain_model_registry FOR EACH ROW EXECUTE FUNCTION public.brain_phase23b_model_guard();
CREATE POLICY brain_features_read ON public.brain_feature_registry FOR SELECT TO authenticated USING(public.brain_is_internal_reader(company_id)); CREATE POLICY brain_features_admin ON public.brain_feature_registry FOR ALL TO authenticated USING(public.brain_is_administrator(company_id)) WITH CHECK(public.brain_is_administrator(company_id));
CREATE POLICY brain_feature_versions_read ON public.brain_feature_versions FOR SELECT TO authenticated USING(public.brain_is_internal_reader(company_id)); CREATE POLICY brain_feature_versions_admin ON public.brain_feature_versions FOR ALL TO authenticated USING(public.brain_is_administrator(company_id)) WITH CHECK(public.brain_is_administrator(company_id));
CREATE POLICY brain_feature_calculations_read ON public.brain_feature_calculations FOR SELECT TO authenticated USING(public.brain_is_analyst(company_id)); CREATE POLICY brain_feature_calculations_service ON public.brain_feature_calculations FOR INSERT TO authenticated WITH CHECK(public.brain_is_service(company_id));
CREATE POLICY brain_rule_evaluations_read ON public.brain_rule_evaluations FOR SELECT TO authenticated USING(public.brain_is_analyst(company_id)); CREATE POLICY brain_rule_evaluations_service ON public.brain_rule_evaluations FOR INSERT TO authenticated WITH CHECK(public.brain_is_service(company_id));
CREATE POLICY brain_conflicts_read ON public.brain_evidence_conflicts FOR SELECT TO authenticated USING(public.brain_is_internal_reader(company_id)); CREATE POLICY brain_conflicts_service ON public.brain_evidence_conflicts FOR INSERT TO authenticated WITH CHECK(public.brain_is_service(company_id)); CREATE POLICY brain_conflicts_review ON public.brain_evidence_conflicts FOR UPDATE TO authenticated USING(public.brain_is_reviewer(company_id)) WITH CHECK(public.brain_is_reviewer(company_id));
CREATE POLICY brain_confidence_read ON public.brain_confidence_policies FOR SELECT TO authenticated USING(company_id IS NULL OR public.brain_is_administrator(company_id)); CREATE POLICY brain_confidence_admin ON public.brain_confidence_policies FOR ALL TO authenticated USING(company_id IS NOT NULL AND public.brain_is_administrator(company_id)) WITH CHECK(company_id IS NOT NULL AND public.brain_is_administrator(company_id));
CREATE POLICY brain_correlations_read ON public.brain_insight_correlations FOR SELECT TO authenticated USING(public.brain_is_internal_reader(company_id)); CREATE POLICY brain_correlations_service ON public.brain_insight_correlations FOR INSERT TO authenticated WITH CHECK(public.brain_is_service(company_id));
CREATE POLICY brain_explanations_read ON public.brain_explanations FOR SELECT TO authenticated USING(public.brain_is_internal_reader(company_id)); CREATE POLICY brain_explanations_service ON public.brain_explanations FOR INSERT TO authenticated WITH CHECK(public.brain_is_service(company_id));
CREATE POLICY brain_queries_read ON public.brain_query_definitions FOR SELECT TO authenticated USING(public.brain_is_analyst(company_id)); CREATE POLICY brain_queries_admin ON public.brain_query_definitions FOR ALL TO authenticated USING(public.brain_is_administrator(company_id)) WITH CHECK(public.brain_is_administrator(company_id)); CREATE POLICY brain_query_exec_read ON public.brain_query_executions FOR SELECT TO authenticated USING(public.brain_is_analyst(company_id)); CREATE POLICY brain_query_exec_insert ON public.brain_query_executions FOR INSERT TO authenticated WITH CHECK(public.brain_is_analyst(company_id) AND executed_by=auth.uid());
CREATE POLICY brain_quality_read ON public.brain_intelligence_quality FOR SELECT TO authenticated USING(public.brain_is_internal_reader(company_id)); CREATE POLICY brain_quality_service ON public.brain_intelligence_quality FOR INSERT TO authenticated WITH CHECK(public.brain_is_service(company_id)); CREATE POLICY brain_quality_review ON public.brain_intelligence_quality FOR UPDATE TO authenticated USING(public.brain_is_reviewer(company_id)) WITH CHECK(public.brain_is_reviewer(company_id));
CREATE POLICY brain_outcomes_read ON public.brain_outcome_records FOR SELECT TO authenticated USING(public.brain_is_internal_reader(company_id)); CREATE POLICY brain_outcomes_review ON public.brain_outcome_records FOR INSERT TO authenticated WITH CHECK(public.brain_is_reviewer(company_id) AND reviewer_id=auth.uid());
CREATE POLICY brain_prompts_read ON public.brain_prompt_registry FOR SELECT TO authenticated USING(company_id IS NULL OR public.brain_is_administrator(company_id)); CREATE POLICY brain_prompts_admin ON public.brain_prompt_registry FOR ALL TO authenticated USING(company_id IS NOT NULL AND public.brain_is_administrator(company_id)) WITH CHECK(company_id IS NOT NULL AND public.brain_is_administrator(company_id)); CREATE POLICY brain_prompt_versions_read ON public.brain_prompt_versions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.brain_prompt_registry p WHERE p.id=prompt_id AND (p.company_id IS NULL OR public.brain_is_administrator(p.company_id)))); CREATE POLICY brain_prompt_versions_admin ON public.brain_prompt_versions FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.brain_prompt_registry p WHERE p.id=prompt_id AND p.company_id IS NOT NULL AND public.brain_is_administrator(p.company_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.brain_prompt_registry p WHERE p.id=prompt_id AND p.company_id IS NOT NULL AND public.brain_is_administrator(p.company_id)));
CREATE POLICY brain_models_read ON public.brain_model_registry FOR SELECT TO authenticated USING(company_id IS NULL OR public.brain_is_administrator(company_id)); CREATE POLICY brain_models_admin ON public.brain_model_registry FOR ALL TO authenticated USING(company_id IS NOT NULL AND public.brain_is_administrator(company_id)) WITH CHECK(company_id IS NOT NULL AND public.brain_is_administrator(company_id));
